INSERT INTO lessons(language_id, cefr_code, slug, title, description, situation, tip, sort_order, status, published_at, updated_at, revision) VALUES ((SELECT id FROM languages WHERE code = 'ta'), 'A1', 'time-days', 'Time and Days', 'Ask the time and talk about the days of the week.', 'Planning your week with your flatmate.', 'Days: nyaayiru (Sun), thingal, sevvaai, budhan, viyaazhan, velli, sani; add “-kkizhamai” for the full name: sanikkizhamai = Saturday. Many people simply say “Sunday” or “Monday”.', 10, 'published', datetime('now'), datetime('now'), 1);
